WITH reference_courses AS (
), candidates AS MATERIALIZED (
SELECT c.id AS course_id, c.institution_id, c.title, c.classification_code, c.recruit_end_date, c.created_at FROM tb_courses c WHERE c.classification_code IS NOT NULL AND ), scored AS ( SELECT c.course_id, c.institution_id, c.title, c.recruit_end_date, c.created_at, s.course_id AS source_course_id, s.course_title AS source_title, s.signal AS source_signal, s.signalled_at, s.classification_code AS reference_code, CASE WHEN c.classification_code = s.classification_code THEN 3 WHEN substr(c.classification_code, 1, 9) = substr(s.classification_code, 1, 9) THEN 2 WHEN substr(c.classification_code, 1, 7) = substr(s.classification_code, 1, 7) THEN 1 ELSE 0 END AS match_level FROM candidates c CROSS JOIN reference_courses s ), best AS ( SELECT DISTINCT ON (course_id) * FROM scored WHERE match_level > 0 ORDER BY course_id, match_level DESC, signalled_at DESC ), ranked AS ( SELECT b.*, COALESCE(p.score, 0) + CASE WHEN b.created_at >= #{freshSince} THEN #{freshBonus} ELSE 0 END AS rank_score, CASE b.match_level WHEN 3 THEN b.reference_code WHEN 2 THEN substr(b.reference_code, 1, 9) || '00' ELSE substr(b.reference_code, 1, 7) || '0000' END AS matched_code FROM best b LEFT JOIN tb_course_popularity p ON p.course_id = b.course_id AND p.segment_type = 'ALL' AND p.segment_key = '*' AND p.window_days = #{windowDays} ), dedup AS ( SELECT DISTINCT ON (institution_id, title) * FROM ranked ORDER BY institution_id, title, recruit_end_date ASC NULLS LAST, created_at DESC ) SELECT d.course_id, d.match_level, d.matched_code, cl.name AS matched_name, d.source_course_id, d.source_title, d.source_signal FROM dedup d LEFT JOIN tb_course_classifications cl ON cl.code = d.matched_code ORDER BY d.match_level DESC, d.rank_score DESC, d.recruit_end_date ASC NULLS LAST, d.created_at DESC LIMIT #{limit}

WITH ranked AS (
    SELECT DISTINCT ON (c.institution_id, c.title)
           p.course_id, p.score, p.enrollment_count
      FROM tb_course_popularity p
      JOIN tb_courses c ON c.id = p.course_id
     WHERE p.segment_type = #{segmentType}
       AND p.segment_key = #{segmentKey}
       AND p.window_days = #{windowDays}
       AND 
     ORDER BY c.institution_id, c.title, c.recruit_end_date ASC NULLS LAST, p.score DESC
)
SELECT course_id::text
  FROM ranked
 ORDER BY score DESC, enrollment_count DESC, course_id
 LIMIT #{limit}

